// Some portions generated by Claude
import { UndirectedGraph } from 'graphology';
import louvain from 'graphology-communities-louvain';
import type { Graph, PointerPosition } from './graph-types.ts';
import { graphNodeSize } from './graph-geometry.ts';
import {LAYOUT_SPACING as gap} from './graph-layout-spacing.ts';
import type { LayoutOptions } from './graph-layout-engine.ts';

export const layoutNodeFixed = (node: Graph['nodes'][number], options: LayoutOptions) => Boolean(
  node.pinned || (options.localNodeIds?.size && !options.localNodeIds.has(node.id)) ||
  (options.incremental && !options.movableNodeIds?.has(node.id)),
);

/** Numeric internal keys isolate the algorithms from arbitrary RDF identifiers. */
export function layoutTopology(graph: Graph) {
  const topology = new UndirectedGraph();
  const index = new Map(graph.nodes.map((node, i) => [node.id, i]));
  graph.nodes.forEach((_, i) => topology.addNode(String(i)));
  graph.edges.forEach(edge => {
    const a = index.get(edge.source), b = index.get(edge.target);
    if (a !== undefined && b !== undefined && a !== b && !topology.hasEdge(a, b)) topology.addEdge(a, b);
  });
  return topology;
}

export function layoutCommunities(graph: Graph) {
  const topology = layoutTopology(graph);
  const partition = louvain(topology, {randomWalk: false, resolution: 1});
  return {topology, partition};
}

export function componentGraphs(graph: Graph): Graph[] {
  const topology = layoutTopology(graph), visited = new Uint8Array(graph.nodes.length);
  const owner = new Int32Array(graph.nodes.length), parts: Graph[] = [];
  for (let seed = 0; seed < graph.nodes.length; seed++) {
    if (visited[seed]) continue;
    const queue = [seed], part: Graph = {nodes: [], edges: [], revision: graph.revision};
    visited[seed] = 1;
    for (let i = 0; i < queue.length; i++) {
      const node = queue[i];
      owner[node] = parts.length;
      topology.forEachNeighbor(String(node), id => {
        const next = Number(id);
        if (!visited[next]) {visited[next] = 1; queue.push(next);}
      });
    }
    parts.push(part);
  }
  const index = new Map(graph.nodes.map((node, i) => [node.id, i]));
  graph.nodes.forEach((node, i) => parts[owner[i]].nodes.push(node));
  graph.edges.forEach(edge => {
    const source = index.get(edge.source), target = index.get(edge.target);
    if (source !== undefined && target !== undefined) parts[owner[source]].edges.push(edge);
  });
  return parts;
}

/** Shelf-pack whole components, never their individual nodes. No fake links. */
export function packLayoutComponents(parts: Graph[], positions: Map<string, PointerPosition>, aspect = 1.6) {
  if (parts.length < 2) return;
  const boxes = parts.map(part => {
    let left = Infinity, right = -Infinity, top = Infinity, bottom = -Infinity;
    for (const node of part.nodes) {
      const p = positions.get(node.id)!, size = graphNodeSize(node);
      left = Math.min(left, p.x - size.width / 2); right = Math.max(right, p.x + size.width / 2);
      top = Math.min(top, p.y - size.height / 2); bottom = Math.max(bottom, p.y + size.height / 2);
    }
    return {part, left, top, width: right - left + gap.groupGap, height: bottom - top + gap.groupGap};
  }).sort((a, b) => b.height - a.height || b.width - a.width);
  const totalArea = boxes.reduce((sum, b) => sum + b.width * b.height, 0);
  const target = Math.max(...boxes.map(b => b.width), Math.sqrt(totalArea * Math.max(.35, Math.min(3, aspect))));
  let x = 0, y = 0, rowHeight = 0;
  for (const box of boxes) {
    if (x && x + box.width > target) {x = 0; y += rowHeight; rowHeight = 0;}
    for (const node of box.part.nodes) {
      const p = positions.get(node.id)!;
      positions.set(node.id, {x: p.x - box.left + x, y: p.y - box.top + y});
    }
    x += box.width; rowHeight = Math.max(rowHeight, box.height);
  }
}
